class Solution:
    def findCircleNum(self, isConnected: List[List[int]]) -> int:
        ans = 0
        n = len(isConnected)
        graph = collections.defaultdict(list)

        for u in range(n):
            for v in range(n):
                if isConnected[u][v]:
                    graph[u].append(v)
                    graph[v].append(u)

        visited = set()
        def dfs(node: int) -> None:
            visited.add(node)
            for nei in graph[node]:
                if nei not in visited:
                    dfs(nei)

        for node in graph.keys():
            if node not in visited:
                dfs(node)
                ans += 1

        return ans
